// === Tab: mySketch ===

function setup(){
	createCanvas(400, 400);
}
rectMode(CENTER);
noStroke();
frameRate(60);
var count=0;
var seg = [];
draw = function() {
    if(frameCount%2===0){    
        count++;
        var te = {x:200,y:200,t:count,c:0,s:0.0,p:[]};
        for(var a=0;a<360;a+=15){
            te.p.push({x:(cos(a/180*Math.PI))*200+random(-15,15),y:(sin(a/180*Math.PI))*200+random(-15,15)});
        }
        seg.unshift(te);
        if(seg.length>200){seg.splice(199,seg.length);}    
    }

    for(var i in seg){
        var t = seg[i];

        t.s += (tan(i/180*Math.PI))/300;

        pushMatrix();
        translate(t.x,t.y);

        scale(t.s);

        fill(constrain(exp(i/21),0,255));

        if(t.t%10===0){
            rect(-100,0,25,350);
            rect(100,0,25,350);
            rect(0,-100,400,46);

        }
        if(t.t%5===0){
            rect(0,146,120,15);
        }

        fill(constrain(exp(i/17),0,255));
        rect(40,145,8,35);
        rect(-40,145,8,35);

        fill(constrain(exp(i/18),0,255));

        for(var j in t.p){
            rect(t.p[j].x,t.p[j].y,65,65);
        }

        popMatrix();
    }

};
